SELECT Go.Sede, Differenza.IdP AS N, "" AS [Num progressivo del minore], Go.IdMinoriMIS, Go.Nome AS [Nome MSNA], Go.Cognome AS [Cognome MSNA], Go.DataN AS [Data di nascita], Go.Cittadinanza, Go.Sesso AS Genere, "Struttura" AS [Tipologia di accoglienza (struttura/privato)], TipoData.Tipo, Comunita.Comunita AS Denominazione, Comunita.Via AS Indirizzo, Comunita.Struttura AS [Ente gestore struttura di accoglienza], Differenza.IdT, Differenza.Data1 AS [Periodo di accoglienza DAL], Differenza.Ora1, Differenza.Data AS [Periodo di accoglienza AL], Differenza.Ora, Differenza.Diff, Differenza.Retta
FROM (Comunita INNER JOIN (Differenza INNER JOIN [Go] ON Differenza.IdP = Go.IdP) ON Comunita.IdC = Differenza.IdC) INNER JOIN TipoData ON Differenza.IdT = TipoData.IdT;
